results = []
for name, cmd, pats, to in CHECKS:
    t0 = time.time()
    try:
        env = dict(__import__('os').environ, PYTHONIOENCODING='utf-8')
        out = subprocess.run([sys.executable, "-u"] + cmd, capture_output=True, text=True, timeout=to, env=env,
                             encoding="utf-8", errors="replace").stdout
        bad = [p for p in pats if not re.search(p, out)]
        ok = not bad
        if cmd[0] == "kary_check.py": ok = ok and "match=False" not in out
        if cmd[0] == "tern_check_all.py": ok = ok and ": False" not in out
    except subprocess.TimeoutExpired:
        ok, bad = False, ["timeout"]
    results.append((name, ok, time.time() - t0, bad))
    print(f"{'PASS' if ok else 'FAIL'}  {name}  ({time.time() - t0:.0f}s){'' if ok else '  missing: ' + str(bad)}", flush=True)
print(f"\n{sum(r[1] for r in results)}/{len(results)} checks passed")
